use aap::caps::inference_llm::infer;
use aap::caps::types::{
    EscalationRequest, ModeratedQuery, ModerationResult, PolicyViolation,
};

struct Node;

impl Guest for Node {
    fn run(query: CustomerQuery) -> ModerationResult {
        // Contract: requires len(question) <= 512. The node only ever receives
        // inputs satisfying this; if it somehow didn't, treat it as a policy
        // violation rather than acting on an out-of-contract input.
        if query.question.chars().count() > 512 {
            return ModerationResult::Violation(PolicyViolation {
                reason: "question exceeds maximum length".to_string(),
            });
        }

        let system = "You are a content moderator for customer support \
            queries. Respond with exactly one word: \"ok\" if the question is \
            safe to answer, \"violation\" if it contains content that \
            violates policy (e.g. abuse, illegal requests, harassment), or \
            \"escalation\" if it requires human review (e.g. threats of \
            self-harm, legal threats, highly sensitive account issues).";

        let verdict = infer(system, &query.question, "moderate");
        let verdict_lower = verdict.trim().to_lowercase();

        if verdict_lower.contains("violation") {
            ModerationResult::Violation(PolicyViolation {
                reason: "content flagged by moderation model".to_string(),
            })
        } else if verdict_lower.contains("escalat") {
            ModerationResult::Escalation(EscalationRequest {
                query,
                reason: "flagged for human review by moderation model".to_string(),
            })
        } else {
            ModerationResult::Ok(ModeratedQuery { query })
        }
    }
}

export!(Node);
